import os
import sys
from xml.dom import minidom

root = "unpacked_report"
document_path = os.path.join(root, "word", "document.xml")
if not os.path.isdir(root):
    print("NO_DIR"); sys.exit(1)

print("FILES:")
for base, dirs, files in os.walk(root):
    for f in files:
        p = os.path.join(base, f)
        print(" ", p)

print("\nPARAGRAPH MAP:")
doc = minidom.parse(document_path)
ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
def qn(tag):
    return f"{{{ns}}}{tag}"

def para_text(p):
    parts = []
    for node in p.getElementsByTagName(qn("t")):
        if node.parentNode.tagName == qn("t"):
            pass
        # Only direct run text, not inside deleted/inserted
        parts.append(node.firstChild.nodeValue if node.firstChild else "")
    return "".join(parts)

for i, p in enumerate(doc.getElementsByTagName(qn("p"))):
    style = ""
    pPr = p.getElementsByTagName(qn("pPr"))
    if pPr:
        pStyle = pPr[0].getElementsByTagName(qn("pStyle"))
        if pStyle:
            style = pStyle[0].getAttribute(qn("val"))
    text = para_text(p)
    print(f"P{i:03d} style={style!r} text={text!r}")

import sys
from collections import Counter
from defusedxml import minidom

DOC = "unpacked/word/document.xml"
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

doc = minidom.parse(DOC)
paras = doc.getElementsByTagName("w:p")

style_counter = Counter()
samples = {}
for p in paras:
    style = None
    for child in p.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.localName == "pPr":
            for c in child.childNodes:
                if c.nodeType == c.ELEMENT_NODE and c.localName == "pStyle":
                    style = c.getAttribute("w:val")
    text = "".join(
        t.data
        for t in p.getElementsByTagName("w:t")
    )
    style_counter[style] += 1
    samples.setdefault(style, []).append(text[:100])

print("== Paragraph style usage ==")
for style, count in style_counter.most_common():
    print(f"{style!r}: {count}")
    for s in samples[style][:3]:
        print(f"    sample: {s!r}")

# Any tracked changes or special structures present?
for tag in ("w:ins", "w:del", "w:hyperlink", "w:bookmarkStart"):
    print(f"{tag}: {len(doc.getElementsByTagName(tag))}")

# Show the paragraph style ids defined in styles.xml
try:
    sdoc = minidom.parse("unpacked/word/styles.xml")
    ids = [
        s.getAttribute("w:styleId")
        for s in sdoc.getElementsByTagName("w:style")
        if s.getAttribute("w:type") == "paragraph"
    ]
    print("== paragraph style ids in styles.xml ==")
    print(ids)
except Exception as e:
    print("styles.xml error:", e)

import os
import sys


def _dom():
    try:
        from defusedxml import minidom
    except Exception:
        from xml.dom import minidom
    return minidom


def _element_children(node):
    return [c for c in node.childNodes if c.nodeType == node.ELEMENT_NODE]


def _run_text(para):
    parts = []
    for t in para.getElementsByTagName("w:t"):
        for c in t.childNodes:
            if c.nodeType == c.TEXT_NODE:
                parts.append(c.data)
    return "".join(parts)


RPRANK = [
    "w:rStyle", "w:rFonts", "w:b", "w:bCs", "w:i", "w:iCs", "w:caps",
    "w:smallCaps", "w:strike", "w:dstrike", "w:outline", "w:shadow",
    "w:emboss", "w:imprint", "w:noProof", "w:snapToGrid", "w:vanish",
    "w:webHidden", "w:color", "w:spacing", "w:w", "w:kern", "w:position",
    "w:sz", "w:szCs", "w:highlight", "w:u", "w:effect", "w:bdr", "w:shd",
    "w:fitText", "w:vertAlign", "w:rtl", "w:cs", "w:em", "w:lang",
    "w:eastAsianLayout", "w:specVanish", "w:oMath",
]
U_RANK = RPRANK.index("w:u")


def is_headline(para):
    text = _run_text(para).strip()
    if not text:
        return False
    cased = [ch for ch in text if ch.isalpha()]
    if not cased:
        return False
    if any(ch.islower() for ch in cased):
        return False
    if any(ch in text for ch in ("\u2022", "\u2023", "\u25aa", "\u00b7", "\u25cf")):
        return False
    return True


def underline_paragraph(para, dom):
    for r in para.getElementsByTagName("w:r"):
        rprs = _element_children(r)
        rprs = [c for c in rprs if c.tagName == "w:rPr"]
        if not rprs:
            rpr = dom.createElement("w:rPr")
            r.insertBefore(rpr, r.firstChild)
        else:
            rpr = rprs[0]
        us = [c for c in _element_children(rpr) if c.tagName == "w:u"]
        if us:
            us[0].setAttribute("w:val", "single")
            continue
        u = dom.createElement("w:u")
        u.setAttribute("w:val", "single")
        kids = _element_children(rpr)
        pos = None
        for i, c in enumerate(kids):
            try:
                if RPRANK.index(c.tagName) > U_RANK:
                    pos = i
                    break
            except ValueError:
                continue
        if pos is None:
            rpr.appendChild(u)
        else:
            rpr.insertBefore(u, kids[pos])


def paragraph_texts(dom):
    return [_run_text(p) for p in dom.getElementsByTagName("w:p")]


def main():
    src = sys.argv[1] if len(sys.argv) > 1 else "unpacked"
    xml_path = os.path.join(src, "word", "document.xml")
    minidom = _dom()

    dom = minidom.parse(xml_path)
    before = paragraph_texts(dom)

    headings = [p for p in dom.getElementsByTagName("w:p") if is_headline(p)]
    for p in headings:
        underline_paragraph(p, dom)

    with open(xml_path, "w", encoding="utf-8") as fh:
        dom.writexml(fh, encoding="utf-8")

    dom2 = minidom.parse(xml_path)
    after = paragraph_texts(dom2)
    if before != after:
        print("ERROR: paragraph text changed during edit")
        return 1

    done = []
    for p in dom2.getElementsByTagName("w:p"):
        if not is_headline(p):
            continue
        text = _run_text(p).strip()
        us = [c for r in p.getElementsByTagName("w:r")
              for c in _element_children(r) if c.tagName == "w:rPr"]
        us = [c for rpr in us for c in _element_children(rpr) if c.tagName == "w:u"]
        ok = all(u.getAttribute("w:val") == "single" for u in us) and len(us) > 0
        if not ok:
            print("ERROR: headline not underlined:", text)
            return 1
        done.append(text)

    print("UNDERLINED_HEADLINES=%d" % len(done))
    for t in sorted(done):
        print(" -", t)
    return 0


if __name__ == "__main__":
    sys.exit(main())

